<script setup lang="ts">
import { ref, computed, watch, onMounted } from 'vue'
import { Download, ShieldCheck } from '@lucide/vue'
import { notifyError, state, api, action, download, saveFile, refresh } from '../store'
import { date } from '../presentation'
import type { RecordData } from '../types'
import Context from '../components/Context.vue'
import GovernanceTarget from '../components/GovernanceTarget.vue'
import QualityPanel from '../components/QualityPanel.vue'
const staff = computed(() => state.sessionScope === 'admin')
const targetJob = ref(''); const monitoringReason = ref(''); const auditOffset = ref(0)
const canGovern = computed(() => !state.busy && !!activeJob.value && (!staff.value || monitoringReason.value.trim().length >= 5))
const activeJob = computed(() => staff.value ? targetJob.value : state.jobId)
const tab = ref('audit'); const audit = ref<RecordData | null>(null); const memory = ref<RecordData[]>([]); const checkResult = ref<RecordData | null>(null); const resumeChecked = ref(false)
const configName = ref('rubric'); const configText = ref(''); const rubric = ref<RecordData | null>(null); const packFile = ref<File | null>(null); const confirmation = ref('')
const names: Record<string,string> = { rubric: '行为判据', priorities: '维度优先级', preferences: '双边偏好维度', 'major-map': '专业映射', presentation: '呈现规范' }
async function loadMemory() { memory.value = staff.value ? targetJob.value ? await api<RecordData[]>('/admin/governance/memory?job_id=' + encodeURIComponent(targetJob.value)) : [] : await api<RecordData[]>('/memory') }
async function load() { try { const [a,r] = await Promise.all([api(staff.value ? '/admin/governance/audit?offset=' + auditOffset.value : '/audit/summary'),api('/config/rubric')]); audit.value = a; rubric.value = r; await loadMemory() } catch(e) { notifyError(e) } }
watch(targetJob, () => { checkResult.value = null; void loadMemory().catch(notifyError) })
async function auditPage(step:number) { auditOffset.value = Math.max(0,auditOffset.value + step * 30); await load() }
async function jobAction(operation:string) { await action(async () => { if (!activeJob.value) return; checkResult.value = staff.value ? await api(`/admin/governance/jobs/${encodeURIComponent(activeJob.value)}/${operation}`,'POST',{reason:monitoringReason.value}) : await api(operation === 'benchmark' ? '/benchmarks/build' : operation === 'resume' ? '/assessments/resume-job/' + activeJob.value : '/audit/drift-check','POST',operation === 'benchmark' ? {job_id:activeJob.value} : undefined); resumeChecked.value = false; await load() }) }
async function exportAudit() { if (staff.value) saveFile(new Blob([JSON.stringify(audit.value?.logs || [],null,2)],{type:'application/json'}),'当前页审计元数据.json'); else await download('/audit/export','审计记录.md') }
let configSequence = 0
async function loadConfig() { const ticket = ++configSequence; try { const c = await api('/config/' + configName.value); if (ticket === configSequence) configText.value = JSON.stringify(c,null,2) } catch(e) { if (ticket === configSequence) notifyError(e) } }
onMounted(() => { load(); loadConfig() }); watch(configName, loadConfig)
async function check(path: string) { await action(async () => { checkResult.value = await api(path,'POST'); await load() }) }
async function exportPack() { await action(async () => { const p = await api('/config/packs/export'); saveFile(new Blob([JSON.stringify(p,null,2)], { type: 'application/json' }), 'standard-pack.json') }) }
async function importPack() { await action(async () => { if (!packFile.value) return; const text = await packFile.value.text(); let data; try { data = JSON.parse(text) } catch { throw new Error('文件不是有效 JSON。') } await api('/config/packs/import','POST',data); await refresh(); await load(); await loadConfig() }, '标准包已校验并导入，历史报告保留原快照。') }
async function saveConfig() { await action(async () => { let data; try { data = JSON.parse(configText.value) } catch { throw new Error('配置不是有效 JSON。') } await api('/config/' + configName.value,'PUT',data); await refresh(); await load() }, '新版本已保存；已有结果不会静默重算。') }
async function updateMemory(id: string, value: string) { await action(async () => { if (staff.value) await api(`/admin/governance/memory/${id}/${value}`,'POST',{reason:monitoringReason.value}); else await api('/memory/' + id,'PUT',{ action: value }); await load() }, '记忆状态已更新。') }
async function purge() { await action(async () => { const r = await api('/maintenance/purge','POST',{ env: state.health?.env, confirmation: confirmation.value }); confirmation.value = ''; await refresh(); await load(); state.success = '合成业务数据已清理，备份：' + r.backup }) }
</script>
<template>
  <div class="page-heading"><p class="eyebrow">内部维护 / 记录与标准</p><h1>审计与标准配置</h1><p>保留每次调用、人工修正与配置更新的来路。</p></div><div class="tabs"><button v-for="(label,key) in { audit: '审计与记忆', config: '标准配置', checks: '内部自检', quality: '质量看板' }" :key="key" :class="{ active: tab === key }" @click="tab = key">{{ label }}</button></div>
  <section v-if="staff" class="surface settings-section"><h2>平台监管范围</h2><p class="muted">审计覆盖当前环境的各企业与求职者调用元数据；校准、恢复及重跑操作只针对选中的企业岗位，并记录工作人员及依据。</p><GovernanceTarget v-model="targetJob" /><label>治理操作依据<textarea v-model="monitoringReason" rows="2" minlength="5" maxlength="1000" placeholder="填写至少 5 个字符的核查依据；查看审计不调用模型，重跑可能产生费用。" /></label></section>
  <template v-if="tab === 'audit' && audit"><div class="audit-strip surface"><div><small>审计记录</small><strong>{{ audit.total ?? audit.logs.length }}</strong></div><div><small>待关注告警</small><strong>{{ audit.alerts }}</strong></div><div><small>估算 AI 成本</small><strong>¥ {{ audit.cost_cny.toFixed(3) }}</strong></div><button class="secondary" :disabled="state.busy" @click="action(exportAudit)"><Download :size="16" />导出记录</button></div><p class="muted">费用按服务器配置的 token 单价估算，实际金额以供应商账单为准。</p><div class="button-row"><button class="secondary" :disabled="state.busy" @click="check('/audit/bias-check')">检查敏感属性隔离</button><button class="secondary" :disabled="!canGovern" @click="jobAction('drift')">重跑锚定样本</button></div><p v-if="checkResult" class="notice">{{ checkResult.note || checkResult.message || '已完成比较，详细结果已写入审计日志。' }}</p><div class="surface table-wrap"><table><thead><tr><th>时间</th><th v-if="staff">所属工作空间</th><th>事件</th><th>结果</th><th>详情</th></tr></thead><tbody><tr v-for="r in audit.logs" :key="r.id"><td>{{ date(r.created_at) }}</td><td v-if="staff">{{ r.owner }}</td><td>{{ r.event_type }}</td><td><span :class="['pill',{ amber: r.result === '告警' }]">{{ r.result }}</span></td><td><details><summary>展开详情</summary><pre>{{ JSON.stringify(r.detail,null,2) }}</pre></details></td></tr></tbody></table></div><div v-if="staff && audit.total > 30" class="button-row"><button class="secondary" :disabled="state.busy || auditOffset === 0" @click="auditPage(-1)">上一页</button><span>{{ auditOffset + 1 }}–{{ Math.min(auditOffset + 30,audit.total) }} / {{ audit.total }}</span><button class="secondary" :disabled="state.busy || auditOffset + 30 >= audit.total" @click="auditPage(1)">下一页</button></div><div class="section-heading"><h2>校准记忆</h2><span>仅确认后用于后续分析</span></div><div class="surface"><article v-for="m in memory.filter(m => !m.deleted_at)" :key="m.id" class="memory-row"><div><h3>{{ m.pattern }}</h3><p>{{ m.confirmed ? '已确认，下次 AI 分析可引用' : '待确认，不自动注入分析' }}</p></div><div class="button-row"><button class="secondary" :disabled="state.busy || m.confirmed || (staff && !canGovern)" @click="updateMemory(m.id,'confirm')">确认记忆</button><button class="text-link danger-link" :disabled="state.busy || (staff && !canGovern)" @click="updateMemory(m.id,'delete')">移除</button></div></article><p v-if="!memory.some(m => !m.deleted_at)" class="empty compact">尚未产生校准记忆。</p></div><details class="surface settings-section"><summary>恢复已暂停的岗位分析</summary><GovernanceTarget v-if="staff" v-model="targetJob" /><Context v-else /><label class="check"><input v-model="resumeChecked" type="checkbox">已检查岗位画像和行为判据</label><button class="secondary" :disabled="!canGovern || !resumeChecked" @click="jobAction('resume')">手动恢复分析</button></details></template>
  <template v-else-if="tab === 'config'"><p class="notice">当前判据：{{ rubric?.version }} · {{ rubric?.status }}。新分析使用当前配置；历史报告保留原快照。</p><section class="surface settings-section"><div class="section-heading"><div><h2>标准包</h2><p class="muted">在完整配置之间保持同一口径。</p></div><button class="secondary" @click="exportPack" :disabled="state.busy"><Download :size="16" />导出标准包</button></div><label>选择标准包 JSON 文件<input type="file" accept=".json" @change="packFile = ($event.target as HTMLInputElement).files?.[0] || null"></label><button class="secondary" @click="importPack" :disabled="state.busy || !packFile">校验并导入标准包</button></section><section class="surface settings-section"><label>选择配置<select v-model="configName"><option v-for="(label,key) in names" :key="key" :value="key">{{ label }}</option></select></label><details><summary>内部配置编辑器</summary><p class="muted">内部维护视图允许查看量规原文。修改须使用新版本号，保存前服务端会校验。</p><label>配置 JSON<textarea v-model="configText" class="code-editor" rows="22" spellcheck="false" /></label><button class="primary" @click="saveConfig" :disabled="state.busy">校验并保存新版本</button></details></section><details class="surface settings-section"><summary>演示数据维护</summary><p>仅清理非生产环境的合成业务数据，先备份，再清理并检查引用完整性。</p><label>输入「清理合成数据」确认<input v-model="confirmation" autocomplete="off"></label><div class="button-row"><button class="danger" :disabled="state.busy || confirmation !== '清理合成数据'" @click="purge">备份并清理</button><button class="secondary" :disabled="state.busy" @click="action(async () => { await api('/demo/seed','POST'); await refresh(); await load() }, '合成示例已装载。')">重新装载合成示例</button></div></details></template>
  <template v-else-if="tab === 'quality'"><QualityPanel :job-id="activeJob" :staff="staff" /></template>
  <template v-else><section class="surface settings-section"><ShieldCheck :size="30" /><h2>标准自检</h2><p>内部工具检查输入标准与统计口径。模型准确率与偏见指标须通过独立人工标注集验证。</p><button class="primary" :disabled="state.busy" @click="check('/selfcheck/identifiability')">运行规则冒烟检查</button><template v-if="checkResult?.fixture_examples"><div class="table-wrap"><table><thead><tr><th>预期方向</th><th>实际方向</th></tr></thead><tbody><tr v-for="(r,i) in checkResult.fixture_examples" :key="i"><td>{{ r.expected }}</td><td>{{ r.actual }}</td></tr></tbody></table></div><p class="notice">{{ checkResult.note }}</p></template></section><section class="surface settings-section"><h2>生成同类岗位参考基准</h2><p>需满足当前判据口径与每项至少 20 份样本。样本不足时服务端明确拦截。</p><GovernanceTarget v-if="staff" v-model="targetJob" /><Context v-else /><button class="secondary" :disabled="!canGovern" @click="jobAction('benchmark')">生成岗位基准</button><p v-if="checkResult?.message" class="notice">{{ checkResult.message }}</p></section></template>
</template>
